"""Money helpers."""

import math
from decimal import Decimal
from fractions import Fraction


def _to_fraction(w):
    if isinstance(w, float):
        if math.isnan(w) or math.isinf(w):
            raise ValueError("weight must be finite")
        return Fraction(w)
    if isinstance(w, Decimal):
        if not w.is_finite():
            raise ValueError("weight must be finite")
        return Fraction(w)
    if isinstance(w, (int, Fraction)):
        return Fraction(w)
    raise ValueError("unsupported weight type: %r" % type(w).__name__)


def allocate(total_cents, weights):
    """Split total_cents across weights. See TASK.md for the full spec."""
    if not isinstance(total_cents, int) or isinstance(total_cents, bool):
        raise ValueError("total_cents must be an int")
    fracs = [_to_fraction(w) for w in weights]
    if not fracs:
        raise ValueError("weights must not be empty")
    if any(f < 0 for f in fracs):
        raise ValueError("weights must not be negative")
    weight_sum = sum(fracs, Fraction(0))
    if weight_sum == 0:
        raise ValueError("weights must not all be zero")

    amount = abs(total_cents)
    shares = []
    rems = []
    for f in fracs:
        exact = amount * f / weight_sum
        fl = exact.numerator // exact.denominator
        shares.append(fl)
        rems.append(exact - fl)

    leftover = amount - sum(shares)
    order = sorted(
        (i for i, f in enumerate(fracs) if f > 0),
        key=lambda i: (-rems[i], -fracs[i], i),
    )
    for i in order[:leftover]:
        shares[i] += 1

    if total_cents < 0:
        shares = [-s for s in shares]
    return shares

